import { test, expect } from '@playwright/test';

test.describe('Sauce Demo Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 });
    await page.goto('https://www.saucedemo.com');
  });

  test('User can log in and see inventory page', async ({ page }) => {
    await page.fill(getByLabel('Username'), 'standard_user');
    await page.fill(getByLabel('Password'), 'secret_sauce');
    await page.click(getByRole('button', { name: /login/i }));
    await expect(page.getByText('Products')).toBeVisible();
  });

  test('Burger menu is visible and opens side menu', async ({ page }) => {
    await page.fill(getByLabel('Username'), 'standard_user');
    await page.fill(getByLabel('Password'), 'secret_sauce');
    await page.click(getByRole('button', { name: /login/i }));

    const burgerMenuButton = page.getByRole('button', { name: /open menu/i });
    await expect(burgerMenuButton).toBeVisible();
    await burgerMenuButton.click();

    const sideMenu = page.locator('.bm-menu');
    await expect(sideMenu).toBeVisible();
    const logoutLink = sideMenu.locator('#logout_sidebar_link');
    await expect(logoutLink).toBeVisible();
  });
});
